<?php
declare(strict_types=1);namespace TalentHub\Modules\School\Repository;use PDO;
final class DatabaseSchoolAiRefreshJobRepository{public function __construct(private readonly PDO $pdo){}public function enqueue(string $schoolId,string $aggregateHash):void{$sqlite=$this->pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite';$sql=$sqlite?'INSERT OR IGNORE INTO school_ai_refresh_jobs (school_id,aggregate_hash,status,attempts,created_at,updated_at) VALUES (?,?,\'pending\',0,?,?)':'INSERT IGNORE INTO school_ai_refresh_jobs (school_id,aggregate_hash,status,attempts,created_at,updated_at) VALUES (?,?,\'pending\',0,?,?)';$now=gmdate('Y-m-d H:i:s');$this->pdo->prepare($sql)->execute([$schoolId,$aggregateHash,$now,$now]);}public function claim():?array{$now=gmdate('Y-m-d H:i:s');$s=$this->pdo->prepare("SELECT id,school_id,aggregate_hash FROM school_ai_refresh_jobs WHERE status='pending' AND (next_retry_at IS NULL OR next_retry_at<=?) ORDER BY created_at,id LIMIT 1");$s->execute([$now]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($row))return null;$u=$this->pdo->prepare("UPDATE school_ai_refresh_jobs SET status='processing',attempts=attempts+1,updated_at=? WHERE id=? AND status='pending'");$u->execute([$now,$row['id']]);return $u->rowCount()===1?$row:null;}public function complete(int $id):void{$this->pdo->prepare("UPDATE school_ai_refresh_jobs SET status='completed',next_retry_at=NULL,updated_at=? WHERE id=?")->execute([gmdate('Y-m-d H:i:s'),$id]);}public function fail(int $id):void{$s=$this->pdo->prepare('SELECT attempts FROM school_ai_refresh_jobs WHERE id=?');$s->execute([$id]);$attempts=(int)$s->fetchColumn();$dead=$attempts>=3;$this->pdo->prepare("UPDATE school_ai_refresh_jobs SET status=?,next_retry_at=?,updated_at=? WHERE id=?")->execute([$dead?'dead_letter':'pending',$dead?null:gmdate('Y-m-d H:i:s',time()+min(3600,2**max(1,$attempts))),gmdate('Y-m-d H:i:s'),$id]);}}
